const body = $input.first().json.body || $input.first().json;
const { group_id, candidate_name, message } = body;
if (!group_id || !candidate_name || !message) throw new Error('group_id, candidate_name, and message are required');

const blocked = [
  /ignore (all |previous |prior )?instructions/i,
  /pretend (you are|to be)/i,
  /you are now/i,
  /act as (if you are|a|an)/i,
  /just (give|tell|show|write|type) (me )?(the )?(answer|solution|code|fix)/i,
  /what is the (answer|solution|correct code|bug)/i,
  /reveal (the |your )?(answer|solution|codebase)/i,
  /bypass|jailbreak|dan mode|developer mode/i,
  /forget (your |the )?instructions/i,
  /system prompt|system message/i,
  /disregard (your |all )?rules/i,
  /tell me (exactly |directly )?(what|where|how) to fix/i,
  /give me the (correct|fixed|working|right) (code|solution|answer)/i
];

const isInjection = blocked.some(re => re.test(message));
const safeName = String(candidate_name).toLowerCase().trim().replace(/\s+/g,'_').replace(/[^a-z0-9_]/g,'');
const safeGroup = String(group_id).replace(/[^a-z0-9_-]/gi,'');
const p_key = `${safeGroup}_${safeName}`;
const session_key = `session_${p_key}`;

return [{ json: {
  group_id: safeGroup,
  candidate_name: String(candidate_name).trim(),
  message: String(message).trim(),
  p_key,
  session_key,
  is_injection: isInjection
} }];

const guardData   = $('Injection Guard').first().json;
const ragData     = $('Fetch RAG Chunks').first().json;
const sessionArr  = $('Fetch Session History').first().json;

const sessionRow  = Array.isArray(sessionArr) ? (sessionArr[0] || {}) : sessionArr;

// Build context from RAG chunks instead of full codebase
const chunks = ragData.chunks || [];
let contextBlock = 'No relevant code found for this question.';
if (chunks.length > 0) {
  contextBlock = chunks.map(c => `--- ${c.filename} ---\n${c.snippet}`).join('\n\n');
}

let messages = [];
try {
  messages = typeof sessionRow.messages === 'string'
    ? JSON.parse(sessionRow.messages)
    : (sessionRow.messages || []);
} catch(e) { messages = []; }

const recentMessages = messages.slice(-10);

// Inject RAG-retrieved chunks as first dynamic turn — NOT in systemPrompt
const geminiHistory = [
  { role: 'user', parts: [{ text: 'Here are the relevant code sections from the project (retrieved via RAG):\n---\n' + contextBlock + '\n---' }] },
  { role: 'model', parts: [{ text: 'Understood. I have the relevant code sections. I will use them to guide the student without revealing the code directly.' }] },
  ...recentMessages.map(m => ({
    role: m.role === 'assistant' ? 'model' : 'user',
    parts: [{ text: m.content || '' }]
  }))
];
geminiHistory.push({ role: 'user', parts: [{ text: guardData.message }] });

const systemPrompt = `You are a Socratic AI coding tutor. The student is debugging their code.\n\nYOUR RULES — STRICT COMPLIANCE REQUIRED:\n1. NEVER write code, pseudocode, or direct logic that solves the problem.\n2. NEVER reveal the bug, the fix, or which exact line number is wrong.\n3. If the student pastes the correct code and asks \"Is this right?\", reply: \"Test it and trace the output. What does it return?\" (Never confirm the answer).\n4. Guide ONLY through open questions (e.g., \"What do you think happens when...\", \"Trace the value of X here.\").\n5. Be concise: Maximum 3 sentences.\n6. NEVER quote the reference codebase directly.\nStudent Name: ${guardData.candidate_name}`;

return [{ json: {
  systemPrompt,
  geminiHistory,
  message: guardData.message,
  p_key: guardData.p_key,
  session_key: guardData.session_key,
  candidate_name: guardData.candidate_name,
  group_id: guardData.group_id
} }];

const raw = $input.first().json;
const reply = raw?.candidates?.[0]?.content?.parts?.[0]?.text?.trim()
  || 'I had trouble forming a response. Could you rephrase?';
const ctx = $('Merge + Build Context').first().json;

// Cite which student-facing files grounded the answer. FastAPI already maps
// solution/... -> the student's own filename, and sends no snippet text,
// so nothing here can leak the reference solution.
const ragChunks = $('Fetch RAG Chunks').first().json?.chunks || [];
const sources = [...new Set(ragChunks.map(c => c.filename).filter(Boolean))]
  .map(filename => ({ filename }));

return [{ json: {
  reply,
  sources,
  message:        ctx.message,
  p_key:          ctx.p_key,
  session_key:    ctx.session_key,
  candidate_name: ctx.candidate_name,
  group_id:       ctx.group_id
} }];

const replyData  = $('Extract Tutor Reply').first().json;
const sessionArr = $('Fetch Session History').first().json;
const sessionRow = Array.isArray(sessionArr) ? (sessionArr[0] || {}) : sessionArr;

let messages = [];
try {
  messages = typeof sessionRow.messages === 'string'
    ? JSON.parse(sessionRow.messages)
    : (sessionRow.messages || []);
} catch(e) { messages = []; }

messages.push({ role: 'user',      content: replyData.message });
messages.push({ role: 'assistant', content: replyData.reply   });

return [{ json: {
  session_key: replyData.session_key,
  messages:    messages,
  updated_at:  new Date().toISOString()
} }];

const replyData   = $('Extract Tutor Reply').first().json;
const scoresArr   = $('Fetch Current Scores').first().json;
const scoresRow   = Array.isArray(scoresArr) ? (scoresArr[0] || {}) : scoresArr;
const sessionArr  = $('Fetch Session History').first().json;
const sessionRow  = Array.isArray(sessionArr) ? (sessionArr[0] || {}) : sessionArr;

let messages = [];
try {
  messages = typeof sessionRow.messages === 'string'
    ? JSON.parse(sessionRow.messages)
    : (sessionRow.messages || []);
} catch(e) { messages = []; }

const prevUserMsg = messages.length >= 2
  ? (messages[messages.length - 2]?.content || 'none')
  : 'none — this is the first message';

const turnCount = (scoresRow?.turn_count || 0) + 1;

const systemPrompt = `You are a strict, objective scoring agent. Your ONLY job is to evaluate the quality of a student debugging prompt across 6 metrics.

You evaluate ONLY this single prompt — not the conversation, not the AI reply.
Return ONLY a raw JSON object. No explanation. No markdown. No backticks.

Metrics (score 1-10 each):
- hypothesis: Did they form a testable specific guess about the bug? 1=vague, 10=precise falsifiable hypothesis
- grounding: Did they reference specific code, functions, variables, or line numbers? 1=no reference, 10=precise location
- reasoning: How many logical steps did they connect? 1=one liner, 10=multi-step causal chain
- progression: Compared to previous message, are they improving? 1=exact repeat or regression, 5=first message, 10=clear forward movement
- creativity: Did they consider non-obvious causes (edge cases, env issues, race conditions)? 1=only obvious, 10=genuine lateral thinking
- clarity: Is the prompt specific and unambiguous? 1=incomprehensible, 10=perfectly clear`;

const userPrompt = `Current student message: "${replyData.message}"
Previous student message: "${prevUserMsg}"
AI reply (context only, do not score this): "${replyData.reply}"
This is turn number: ${turnCount}`;

return [{ json: {
  systemPrompt,
  userPrompt,
  p_key:          replyData.p_key,
  group_id:       replyData.group_id,
  candidate_name: replyData.candidate_name,
  turnCount,
  scoresRow: scoresRow || {}
} }];

const raw = $input.first().json;
const rawText = raw?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let newScores;
try {
  const cleaned = rawText.replace(/```json|```/g,'').trim();
  newScores = JSON.parse(cleaned);
} catch(e) {
  newScores = { hypothesis:5, grounding:5, reasoning:5, progression:5, creativity:5, clarity:5 };
}

const clamp = v => Math.min(10, Math.max(1, Number(v) || 5));
const metrics = ['hypothesis','grounding','reasoning','progression','creativity','clarity'];
for (const m of metrics) newScores[m] = clamp(newScores[m]);

const evalData   = $('Build Evaluator Prompt').first().json;
const scoresRow  = evalData.scoresRow || {};
const turnCount  = evalData.turnCount;
const alpha      = 2 / (turnCount + 1);

function ema(oldVal, newVal) {
  if (oldVal === null || oldVal === undefined || oldVal === '') return newVal;
  return parseFloat((alpha * newVal + (1 - alpha) * parseFloat(oldVal)).toFixed(4));
}

const updated = {};
for (const m of metrics) {
  updated[`${m}_ema`] = ema(scoresRow[`${m}_ema`], newScores[m]);
}

let scoreHistory = [];
try {
  scoreHistory = typeof scoresRow.score_history === 'string'
    ? JSON.parse(scoresRow.score_history)
    : (scoresRow.score_history || []);
} catch(e) { scoreHistory = []; }

scoreHistory.push({
  turn:      turnCount,
  timestamp: new Date().toISOString(),
  raw:       newScores
});

return [{ json: {
  p_key:           evalData.p_key,
  group_id:        evalData.group_id,
  candidate_name:  evalData.candidate_name,
  turn_count:      turnCount,
  ...updated,
  score_history:   JSON.stringify(scoreHistory),
  updated_at:      new Date().toISOString()
} }];

const input = $input.first().json;
const headers = input.headers || {};
const query   = input.query   || {};

const adminKey    = headers['x-admin-key'] || headers['X-Admin-Key'] || '';
const expectedKey = $env.ADMIN_SECRET || 'change-me';

if (!adminKey || adminKey !== expectedKey) throw new Error('UNAUTHORIZED');

const { group_id, candidate_name } = query;
if (!group_id || !candidate_name) throw new Error('group_id and candidate_name are required');

const safeName  = String(candidate_name).toLowerCase().trim().replace(/\s+/g,'_').replace(/[^a-z0-9_]/g,'');
const safeGroup = String(group_id).replace(/[^a-z0-9_-]/gi,'');
const p_key = `${safeGroup}_${safeName}`;

return [{ json: { p_key, group_id: safeGroup, candidate_name: String(candidate_name).trim() } }];

const input    = $input.first().json;
const rows     = Array.isArray(input) ? input : [input];
const row      = rows[0] || {};
const authData = $('Auth + Build PKey').first().json;

if (!row.p_key) {
  return [{ json: { found: false, p_key: authData.p_key, candidate_name: authData.candidate_name, group_id: authData.group_id, message: 'No scores found yet' } }];
}

let scoreHistory = [];
try {
  scoreHistory = typeof row.score_history === 'string' ? JSON.parse(row.score_history) : (row.score_history || []);
} catch(e) { scoreHistory = []; }

const metrics = ['hypothesis','grounding','reasoning','progression','creativity','clarity'];
const currentEma = {};
for (const m of metrics) currentEma[m] = parseFloat((row[`${m}_ema`] || 0).toFixed(2));

return [{ json: {
  found:              true,
  p_key:              row.p_key,
  group_id:           row.group_id,
  candidate_name:     row.candidate_name,
  turn_count:         row.turn_count || 0,
  current_ema_scores: currentEma,
  score_history:      scoreHistory,
  created_at:         row.created_at,
  updated_at:         row.updated_at
} }];
